import{_ as t,c as n,o as a,ae as i}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Delete My Account","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Delete My Account","query":"mutation DeleteSelf($input: createAdminSettingsUserDeleteSelfInput!) {\\n  createAdminSettingsUserDeleteSelf(input: $input) {\\n    adminSettingsUserDeleteSelf {\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"password\\": \\"current-password\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminSettingsUserDeleteSelf\\": {\\n      \\"adminSettingsUserDeleteSelf\\": {\\n        \\"success\\": true,\\n        \\"message\\": \\"Your admin account has been deleted.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/users/delete-self.md","filePath":"api/graphql-api/admin/settings/users/delete-self.md"}'),s={name:"api/graphql-api/admin/settings/users/delete-self.md"};function r(o,e,l,d,c,u){return a(),n("div",null,e[0]||(e[0]=[i('<h1 id="delete-my-account" tabindex="-1">Delete My Account <a class="header-anchor" href="#delete-my-account" aria-label="Permalink to &quot;Delete My Account&quot;">​</a></h1><p>Deletes the <strong>authenticated</strong> admin&#39;s own account after re-confirming their password.</p><ul><li>Requires the caller&#39;s current <code>password</code>. A missing or incorrect password returns an <code>errors</code> entry and the account is left intact.</li><li>Refuses to delete the <strong>last remaining</strong> admin.</li><li>Deleting the account <strong>invalidates the Bearer token</strong> that owns it — subsequent requests with that token are unauthenticated.</li><li>Distinct from <a href="./delete.html">Delete User</a>, which removes another admin and always refuses self-deletion.</li></ul><p>No additional permission is required beyond authentication — the password confirmation is the gate.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminSettingsUserDeleteSelf(input:)</code></td><td>Mutation</td><td>Delete your own admin account</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The response above is illustrative. Running this mutation permanently deletes your account and invalidates your token, so it is not executed against the live API in these docs.</p></div><p>All admin endpoints require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',8)]))}const m=t(s,[["render",r]]);export{h as __pageData,m as default};
